## `app.js`

```javascript
/**
 * =============================================
 * TASK MANAGEMENT APPLICATION
 * =============================================
 * A vanilla JavaScript app with localStorage persistence,
 * status-based grouping, filtering, and CRUD operations.
 * =============================================
 */

// ==================== STATE ====================
let tasks = [];          // Array of task objects
let currentFilter = 'all'; // 'all', 'pending', 'in_progress', 'completed'

// ==================== DOM REFERENCES ====================
const taskForm      = document.getElementById('task-form');
const titleInput    = document.getElementById('task-title');
const descInput     = document.getElementById('task-desc');
const formError     = document.getElementById('form-error');
const filterBtns    = document.querySelectorAll('.filter-btn');
const taskCountEl   = document.getElementById('task-count');
const emptyState    = document.getElementById('empty-state');
const lists = {
  pending:     document.getElementById('list-pending'),
  in_progress: document.getElementById('list-in_progress'),
  completed:   document.getElementById('list-completed'),
};

// ==================== LOCAL STORAGE ====================
/**
 * Load tasks from localStorage on app startup.
 * Falls back to an empty array if no data exists or parsing fails.
 */
function loadTasks() {
  try {
    const stored = localStorage.getItem('taskManager_tasks');
    tasks = stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error('Failed to load tasks from localStorage:', e);
    tasks = [];
  }
}

/**
 * Save the current tasks array to localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem('taskManager_tasks', JSON.stringify(tasks));
  } catch (e) {
    console.error('Failed to save tasks to localStorage:', e);
  }
}

// ==================== TASK CREATION ====================
/**
 * Generate a unique ID for new tasks using timestamp + random suffix.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

/**
 * Add a new task from the form inputs.
 * Validates that the title is not empty before creating.
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // default status
    createdAt: new Date().toISOString(),
  };

  tasks.unshift(task); // Add to beginning of array
  saveTasks();
  render();
}

// ==================== TASK DELETION ====================
/**
 * Remove a task by its ID and persist the change.
 */
function deleteTask(id) {
  tasks = tasks.filter((task) => task.id !== id);
  saveTasks();
  render();
}

// ==================== STATUS TOGGLE ====================
/**
 * Cycle a task's status: pending → in_progress → completed → pending
 */
function toggleStatus(id) {
  const task = tasks.find((t) => t.id === id);
  if (!task) return;

  const cycle = ['pending', 'in_progress', 'completed'];
  const currentIndex = cycle.indexOf(task.status);
  task.status = cycle[(currentIndex + 1) % cycle.length];

  saveTasks();
  render();
}

// ==================== FILTERING ====================
/**
 * Update the active filter and re-render.
 */
function setFilter(filter) {
  currentFilter = filter;

  // Update button states
  filterBtns.forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.filter === filter);
  });

  render();
}

/**
 * Return tasks matching the current filter.
 */
function getFilteredTasks() {
  if (currentFilter === 'all') return tasks;
  return tasks.filter((t) => t.status === currentFilter);
}

// ==================== RENDERING ====================
/**
 * Build and insert a task card HTML string.
 */
function createTaskCard(task) {
  const completedClass = task.status === 'completed' ? 'completed' : '';
  const descHtml = task.description
    ? `<p class="task-desc">${escapeHtml(task.description)}</p>`
    : '';

  return `
    <div
      class="task-card ${completedClass}"
      data-id="${task.id}"
      data-status="${task.status}"
      title="Click to cycle status"
    >
      <div class="task-header">
        <span class="task-title">${escapeHtml(task.title)}</span>
        <button
          class="delete-btn"
          data-delete="${task.id}"
          title="Delete task"
          aria-label="Delete ${escapeHtml(task.title)}"
        >✕</button>
      </div>
      ${descHtml}
      <div class="task-footer">
        <span class="status-badge ${task.status}">${formatStatus(task.status)}</span>
        <span class="task-date">${formatDate(task.createdAt)}</span>
      </div>
    </div>
  `;
}

/**
 * Main render function — rebuilds the entire task board.
 */
function render() {
  const filtered = getFilteredTasks();

  // Group tasks by status for column display
  const grouped = {
    pending:     [],
    in_progress: [],
    completed:   [],
  };

  filtered.forEach((task) => {
    grouped[task.status].push(task);
  });

  // Render each column
  Object.entries(lists).forEach(([status, container]) => {
    const taskCards = grouped[status]
      .map((task) => createTaskCard(task))
      .join('');
    container.innerHTML = taskCards;

    // Update column count badge
    const countEl = container.closest('.column').querySelector('.column-count');
    if (countEl) {
      countEl.textContent = tasks.filter((t) => t.status === status).length;
    }
  });

  // Update total task count in filter bar
  taskCountEl.textContent = `${filtered.length} task${filtered.length !== 1 ? 's' : ''}`;

  // Show/hide empty state
  emptyState.classList.toggle('hidden', filtered.length > 0);
}

// ==================== UTILITY FUNCTIONS ====================
/**
 * Escape HTML special characters to prevent XSS.
 */
function escapeHtml(str) {
  const div = document.createElement('div');
  div.appendChild(document.createTextNode(str));
  return div.innerHTML;
}

/**
 * Format a status string into a human-readable label.
 */
function formatStatus(status) {
  return status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * Format an ISO date string into a readable short form.
 */
function formatDate(isoString) {
  const date = new Date(isoString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

// ==================== EVENT LISTENERS ====================

/**
 * Handle form submission — add a new task.
 */
taskForm.addEventListener('submit', (e) => {
  e.preventDefault();

  const title = titleInput.value.trim();
  const desc  = descInput.value.trim();

  // Clear previous error
  formError.textContent = '';

  // Validate
  if (!title) {
    formError.textContent = 'Please enter a task title.';
    titleInput.focus();
    return;
  }

  addTask(title, desc);

  // Reset form
  titleInput.value = '';
  descInput.value  = '';
});

/**
 * Handle filter button clicks.
 */
filterBtns.forEach((btn) => {
  btn.addEventListener('click', () => setFilter(btn.dataset.filter));
});

/**
 * Handle task interactions via event delegation on the board.
 * - Clicking a card toggles its status
 * - Clicking the delete button removes it
 */
document.getElementById('task-board').addEventListener('click', (e) => {
  const card = e.target.closest('.task-card');
  if (!card) return;

  // Delete button clicked
  if (e.target.classList.contains('delete-btn')) {
    e.stopPropagation(); // Prevent status toggle
    deleteTask(card.dataset.id);
    return;
  }

  // Card clicked — cycle status
  toggleStatus(card.dataset.id);
});

// ==================== INITIALIZATION ====================
/**
 * Load saved tasks and render the initial view.
 */
loadTasks();
render();
```

