### `app.js`

```javascript
/**
 * =============================================
 * GERENCIADOR DE TAREFAS — App.js
 * =============================================
 * Aplicação vanilla JS que permite:
 *   - Adicionar, editar status e excluir tarefas
 *   - Agrupar por status (pendente / em_andamento / concluído)
 *   - Filtrar visualização por status
 *   - Persistir dados no localStorage
 * =============================================
 */

// ==================== ESTADO DA APLICAÇÃO ====================

/** Array principal de tarefas. Cada tarefa é um objeto:
 *  { id, title, description, status, createdAt }
 */
let tasks = [];

/** Filtro atualmente ativo: 'todas', 'pendente', 'em_andamento', 'concluído' */
let currentFilter = 'todas';

// ==================== CONSTANTES E SELECTORS DOM ====================

const STORAGE_KEY = 'task_manager_tasks';

const form = document.getElementById('task-form');
const titleInput = document.getElementById('task-title');
const descInput = document.getElementById('task-desc');
const tasksContainer = document.getElementById('tasks-container');
const emptyMessage = document.getElementById('empty-message');

// Badges de contagem nos filtros
const countAll = document.getElementById('count-all');
const countPending = document.getElementById('count-pending');
const countInProgress = document.getElementById('count-in-progress');
const countCompleted = document.getElementById('count-completed');

// Contadores nas seções
const sectionCountPending = document.getElementById('section-count-pending');
const sectionCountInProgress = document.getElementById('section-count-in-progress');
const sectionCountCompleted = document.getElementById('section-count-completed');

// Listas por status
const listPending = document.getElementById('list-pending');
const listInProgress = document.getElementById('list-in-progress');
const listCompleted = document.getElementById('list-completed');

// Botões de filtro
const filterButtons = document.querySelectorAll('.btn-filter');

// Seções por status (para esconder/mostrar)
const taskSections = document.querySelectorAll('.task-section');

// ==================== PERSISTÊNCIA (localStorage) ====================

/**
 * Salva o array de tarefas no localStorage.
 * Chamado sempre que há alteração no estado.
 */
function saveTasks() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
}

/**
 * Carrega as tarefas do localStorage na inicialização.
 * Se não houver dados, inicia com array vazio.
 */
function loadTasks() {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    try {
      tasks = JSON.parse(stored);
    } catch (e) {
      console.error('Erro ao parsear tarefas do localStorage:', e);
      tasks = [];
    }
  }
}

// ==================== GERAÇÃO DE ID ÚNICO ====================

/**
 * Gera um ID único usando timestamp + random.
 * Evita colisão mesmo com múltiplas tarefas criadas no mesmo milissegundo.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

// ==================== ADICIONAR TAREFA ====================

/**
 * Cria e adiciona uma nova tarefa ao estado.
 * Status inicial: 'pendente'.
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pendente',
    createdAt: new Date().toISOString()
  };

  tasks.push(task);
  saveTasks();
  render();
}

// ==================== EXCLUIR TAREFA ====================

/**
 * Remove uma tarefa do estado pelo ID.
 */
function deleteTask(id) {
  tasks = tasks.filter(t => t.id !== id);
  saveTasks();
  render();
}

// ==================== ALTERAR STATUS DA TAREFA ====================

/**
 * Cicla o status da tarefa: pendente → em_andamento → concluído → pendente.
 * Chamado ao clicar no card da tarefa.
 */
function toggleTaskStatus(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // Ciclo de status
  const cycle = {
    'pendente': 'em_andamento',
    'em_andamento': 'concluído',
    'concluído': 'pendente'
  };

  task.status = cycle[task.status];
  saveTasks();
  render();
}

// ==================== CRIAÇÃO DO ELEMENTO DOM DA TAREFA ====================

/**
 * Cria o elemento <li> que representa uma tarefa na lista.
 * @param {Object} task - Objeto da tarefa
 * @returns {HTMLElement} Elemento li da tarefa
 */
function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'task-item';
  li.dataset.status = task.status;
  li.dataset.id = task.id;

  // Mapeia o status para texto legível em português
  const statusLabels = {
    'pendente': 'Pendente',
    'em_andamento': 'Em Andamento',
    'concluído': 'Concluído'
  };

  li.innerHTML = `
    <div class="task-content">
      <div class="task-title">${escapeHtml(task.title)}</div>
      ${task.description ? `<div class="task-desc">${escapeHtml(task.description)}</div>` : ''}
      <span class="status-badge ${task.status}">${statusLabels[task.status]}</span>
    </div>
    <button
      class="btn-delete"
      title="Excluir tarefa"
      aria-label="Excluir: ${escapeHtml(task.title)}"
    >✕</button>
  `;

  // Clique no card alterna o status
  li.addEventListener('click', (e) => {
    // Não alterna se o clique foi no botão de excluir
    if (e.target.closest('.btn-delete')) return;
    toggleTaskStatus(task.id);
  });

  // Clique no botão de excluir remove a tarefa
  li.querySelector('.btn-delete').addEventListener('click', (e) => {
    e.stopPropagation(); // evita disparar o toggle do card
    deleteTask(task.id);
  });

  return li;
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ==================== RENDERIZAÇÃO COMPLETA ====================

/**
 * Reconstrói toda a interface de tarefas com base no estado atual.
 * Agrupa por status, aplica filtro e atualiza contadores.
 */
function render() {
  // Limpa as listas
  listPending.innerHTML = '';
  listInProgress.innerHTML = '';
  listCompleted.innerHTML = '';

  // Contagem por status (para badges e seções)
  const pendingTasks = tasks.filter(t => t.status === 'pendente');
  const inProgressTasks = tasks.filter(t => t.status === 'em_andamento');
  const completedTasks = tasks.filter(t => t.status === 'concluído');

  // Atualiza contadores dos filtros
  countAll.textContent = tasks.length;
  countPending.textContent = pendingTasks.length;
  countInProgress.textContent = inProgressTasks.length;
  countCompleted.textContent = completedTasks.length;

  // Atualiza contadores das seções
  sectionCountPending.textContent = pendingTasks.length;
  sectionCountInProgress.textContent = inProgressTasks.length;
  sectionCountCompleted.textContent = completedTasks.length;

  // Popula as listas
  pendingTasks.forEach(task => listPending.appendChild(createTaskElement(task)));
  inProgressTasks.forEach(task => listInProgress.appendChild(createTaskElement(task)));
  completedTasks.forEach(task => listCompleted.appendChild(createTaskElement(task)));

  // Aplica o filtro de visualização
  applyFilter();

  // Mostra/esconde mensagem de lista vazia
  const hasVisibleTasks = tasks.length > 0;
  emptyMessage.style.display = hasVisibleTasks ? 'none' : 'block';
  tasksContainer.style.display = hasVisibleTasks ? 'flex' : 'none';
}

// ==================== FILTRO DE VISUALIZAÇÃO ====================

/**
 * Mostra/esconde as seções com base no filtro ativo.
 */
function applyFilter() {
  taskSections.forEach(section => {
    const status = section.dataset.status;

    if (currentFilter === 'todas') {
      // Mostra todas as seções que têm tarefas
      section.classList.toggle('hidden', false);
    } else {
      // Mostra apenas a seção correspondente ao filtro
      section.classList.toggle('hidden', status !== currentFilter);
    }
  });
}

/**
 * Configura os botões de filtro.
 */
function setupFilters() {
  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      // Atualiza classe ativa
      filterButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      // Define o filtro e re-renderiza
      currentFilter = btn.dataset.filter;
      applyFilter();
    });
  });
}

// ==================== EVENT LISTENERS PRINCIPAIS ====================

/**
 * Manipula o envio do formulário de adição.
 */
function setupForm() {
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const title = titleInput.value.trim();
    const description = descInput.value.trim();

    if (!title) return; // validação já feita pelo atributo required do HTML

    addTask(title, description);

    // Limpa o formulário
    form.reset();
    titleInput.focus();
  });
}

// ==================== INICIALIZAÇÃO ====================

/**
 * Inicializa a aplicação: carrega dados, configura eventos e renderiza.
 */
function init() {
  loadTasks();       // Carrega do localStorage
  setupForm();       // Configura o formulário
  setupFilters();    // Configura os botões de filtro
  render();          // Renderiza a interface inicial
}

// Inicia quando o DOM estiver pronto
document.addEventListener('DOMContentLoaded', init);
